[
    {
        "title": "设未知量",
        "description": "设每头牛每天吃草量为 $c$，牧草原有量为 $G$，每天生长量为 $r$。",
        "bubbleText": "先把“每头牛吃多少”和“草原本来有多少”记下来，后面才能公平比较两种情况。",
        "bubblePos": {
            "x": 24.0,
            "y": 24.0
        },
        "arrowTarget": {
            "x": 555.0,
            "y": 195.0
        }
    },
    {
        "title": "第一种放牧",
        "description": "10头牛吃20天，共消耗 $10\\times20c=200c$，所以 $G+20r=200c$。",
        "bubbleText": "牛吃掉的草，来自原来的草和这20天新长出来的草。",
        "bubblePos": {
            "x": 24.0,
            "y": 24.0
        },
        "arrowTarget": {
            "x": 552.0,
            "y": 495.0
        }
    },
    {
        "title": "第二种放牧",
        "description": "15头牛吃10天，共消耗 $15\\times10c=150c$，所以 $G+10r=150c$。",
        "bubbleText": "换一种牛数和天数，仍然是同一片草，因此又得到一个等式。",
        "bubblePos": {
            "x": 24.0,
            "y": 24.0
        },
        "arrowTarget": {
            "x": 552.0,
            "y": 495.0
        }
    },
    {
        "title": "求每天生长量",
        "description": "两式相减，消去 $G$：$10r=50c$，得到 $r=5c$；代回得 $G=100c$。",
        "bubbleText": "两种情况相减，原有草量消掉了，只留下生长量，算出每天长出相当于5头牛一天的草。",
        "bubblePos": {
            "x": 24.0,
            "y": 24.0
        },
        "arrowTarget": {
            "x": 552.0,
            "y": 396.0
        }
    },
    {
        "title": "求25头牛天数",
        "description": "25头牛每天净消耗 $(25-5)c=20c$，所以天数为 $100c\\div20c=5$天。",
        "bubbleText": "25头牛中，有5头牛的吃草量正好由新长的草补上，真正消耗原有草的是20头牛。",
        "bubblePos": {
            "x": 24.0,
            "y": 24.0
        },
        "arrowTarget": {
            "x": 675.0,
            "y": 455.0
        }
    },
    {
        "title": "求永远放牧数",
        "description": "若永远吃不完，牛群每天消耗量不能超过生长量：$nc\\le r=5c$，所以 $n\\le5$，最多放牧5头牛。验证：5头牛每天吃 $5c$，恰好等于每天生长的 $5c$，牧草量保持不变。",
        "bubbleText": "放5头时，吃多少就长多少，草的存量不减少，所以最多是5头。",
        "bubblePos": {
            "x": 24.0,
            "y": 24.0
        },
        "arrowTarget": {
            "x": 520.0,
            "y": 515.0
        }
    }
